Here's the Python code to evaluate all Caesar shifts and rank based on simple English word matches:

```python
def caesar_decrypt(text, shift):
    out = []
    for ch in text:
        if ch.isalpha():
            base = ord('A') if ch.isupper() else ord('a')
            out.append(chr((ord(ch) - base - shift) % 26 + base))
        else:
            out.append(ch)
    return ''.join(out)

# crude English scoring using keyword hits
keywords = {"picnic", "is", "in", "plaza"}

cipher = "Zsmxsm sc sx Zyvilsec Zvkjk."
results = []
for s in range(1, 26):
    plain = caesar_decrypt(cipher, s)
    tokens = {t.strip('.').lower() for t in plain.split()}
    score = sum(1 for k in keywords if k in tokens)
    results.append((score, s, plain))

# sort by score descending, then by shift
results.sort(key=lambda x: (-x[0], x[1]))

# print top 3 candidates
for i, (score, shift, plain) in enumerate(results[:3], start=1):
    print(f"Top {i}: shift={shift}, score={score}, text={plain}")
